WITH source AS (SELECT entity_uuid,reported_month,count(*)::bigint AS input_rows,sum(malnutrition) AS malnutrition,sum(mam) AS mam,sum(mas) AS mas,sum(mam_cured) AS mam_cured,sum(mam_abandonment) AS mam_abandonment,sum(mam_no_response) AS mam_no_response,sum(mas_cured) AS mas_cured,sum(mas_abandonment) AS mas_abandonment,sum(mas_no_response) AS mas_no_response FROM (SELECT entity_uuid,reported_month,sum(malnutrition) AS malnutrition,sum(mam) AS mam,sum(mas) AS mas,sum(mam_cured) AS mam_cured,sum(mam_abandonment) AS mam_abandonment,sum(mam_no_response) AS mam_no_response,sum(mas_cured) AS mas_cured,sum(mas_abandonment) AS mas_abandonment,sum(mas_no_response) AS mas_no_response FROM (SELECT s.chw_site_uuid AS entity_uuid,s.reported_month,(coalesce(s.malnutrition_male_inf_1y,0)+coalesce(s.malnutrition_male_sup_1y,0)+coalesce(s.malnutrition_female_inf_1y,0)+coalesce(s.malnutrition_female_sup_1y,0))::numeric AS malnutrition,
(coalesce(s.mam_male_inf_1y,0)+coalesce(s.mam_male_sup_1y,0)+coalesce(s.mam_female_inf_1y,0)+coalesce(s.mam_female_sup_1y,0))::numeric AS mam,
(coalesce(s.mas_no_complication_male_inf_1y,0)+coalesce(s.mas_no_complication_male_sup_1y,0)+coalesce(s.mas_no_complication_female_inf_1y,0)+coalesce(s.mas_no_complication_female_sup_1y,0))::numeric AS mas,
(NULL::numeric)::numeric AS mam_cured,
(NULL::numeric)::numeric AS mam_abandonment,
(NULL::numeric)::numeric AS mam_no_response,
(NULL::numeric)::numeric AS mas_cured,
(NULL::numeric)::numeric AS mas_abandonment,
(NULL::numeric)::numeric AS mas_no_response FROM public.mv_pec_u5_indicators_shared s WHERE s.reported_month>=date_trunc('month',CURRENT_DATE)-interval '12 months' AND s.reported_month<date_trunc('month',CURRENT_DATE) UNION ALL SELECT s.chw_site_id AS entity_uuid,s.reported_month,(NULL::numeric)::numeric AS malnutrition,
(NULL::numeric)::numeric AS mam,
(NULL::numeric)::numeric AS mas,
(coalesce(s.mam_cured_male_inf_1y,0)+coalesce(s.mam_cured_male_sup_1y,0)+coalesce(s.mam_cured_female_inf_1y,0)+coalesce(s.mam_cured_female_sup_1y,0))::numeric AS mam_cured,
(coalesce(s.mam_abandonment_male_inf_1y,0)+coalesce(s.mam_abandonment_male_sup_1y,0)+coalesce(s.mam_abandonment_female_inf_1y,0)+coalesce(s.mam_abandonment_female_sup_1y,0))::numeric AS mam_abandonment,
(coalesce(s.mam_no_response_male_inf_1y,0)+coalesce(s.mam_no_response_male_sup_1y,0)+coalesce(s.mam_no_response_female_inf_1y,0)+coalesce(s.mam_no_response_female_sup_1y,0))::numeric AS mam_no_response,
(coalesce(s.mas_cured_male_inf_1y,0)+coalesce(s.mas_cured_male_sup_1y,0)+coalesce(s.mas_cured_female_inf_1y,0)+coalesce(s.mas_cured_female_sup_1y,0))::numeric AS mas_cured,
(coalesce(s.mas_abandonment_male_inf_1y,0)+coalesce(s.mas_abandonment_male_sup_1y,0)+coalesce(s.mas_abandonment_female_inf_1y,0)+coalesce(s.mas_abandonment_female_sup_1y,0))::numeric AS mas_abandonment,
(coalesce(s.mas_no_response_male_inf_1y,0)+coalesce(s.mas_no_response_male_sup_1y,0)+coalesce(s.mas_no_response_female_inf_1y,0)+coalesce(s.mas_no_response_female_sup_1y,0))::numeric AS mas_no_response FROM public.malnutrition_indicators s WHERE s.reported_month>=date_trunc('month',CURRENT_DATE)-interval '12 months' AND s.reported_month<date_trunc('month',CURRENT_DATE)) x GROUP BY 1,2) raw GROUP BY entity_uuid,reported_month), geography AS (SELECT * FROM public.mv_asc_ops_geography)
    SELECT s.entity_uuid,s.reported_month::date,s.input_rows,g.region_uuid,
      coalesce(g.region,'Hors répertoire courant') AS region,g.district_uuid,
      coalesce(g.district,'Hors répertoire courant') AS district,g.district_name,g.health_area_uuid,
      coalesce(g.cscom,'Hors répertoire courant') AS cscom,g.cscom_name,g.site_uuid,g.site,g.site_name,g.supervision_area,
      CASE WHEN g.site_uuid IS NULL THEN 'Hors répertoire courant' ELSE 'Rattaché au répertoire courant' END AS attribution,
      s.malnutrition,s.mam,s.mas,s.mam_cured,s.mam_abandonment,s.mam_no_response,s.mas_cured,s.mas_abandonment,s.mas_no_response,
      CURRENT_TIMESTAMP AS calculated_at,
      (date_trunc('month',CURRENT_DATE)-interval '12 months')::date AS coverage_start,
      date_trunc('month',CURRENT_DATE)::date AS coverage_end
    FROM source s LEFT JOIN geography g ON g.site_uuid=s.entity_uuid
